use std::borrow::Cow;

use lb_binary_codec::canonical::{
    CodecExamples, CodecFixture, CodecFixtures, codec_fixtures, decode_fixture_hex,
};
use lb_cryptarchia_engine::Slot;
use lb_groth16::Fr;
use lb_key_management_system_keys::keys::{Ed25519Key, Ed25519PublicKey, Ed25519Signature};
use lb_utils::bounded::BoundedOrderedSet;

use crate::{
    block::{
        BlockTransactions, References,
        fixtures::three_references,
        v1::{Block, Proposal, SignedHeader, UncleHeaders},
    },
    header::{ContentId, HeaderId, v1::Header},
    mantle::{
        TxHash,
        ops::leader_claim::VoucherCm,
        traits::{Hashable, StorageSize},
    },
    proofs::leader_proof::Groth16LeaderProof,
};

fn three_uncle_headers() -> UncleHeaders {
    UncleHeaders::new(BoundedOrderedSet::try_from([uncle(0x66), uncle(0x77), uncle(0x88)]).unwrap())
}

fn uncle(id: u8) -> SignedHeader {
    SignedHeader::new(header(id), Ed25519Signature::from_bytes(&[id; _]))
}

fn header(id: u8) -> Header {
    Header::new(
        HeaderId::from([id; 32]),
        ContentId::from([0x22u8; 32]),
        Slot::from(42u64),
        Groth16LeaderProof::from_parts(
            lb_pol::PoLProof::from_bytes(&[0x22u8; _]),
            Fr::from(0x5555u64),
            Ed25519PublicKey::from_bytes(&[0x33u8; _]).expect("valid key bytes"),
            VoucherCm::from(Fr::from(0x4444u64)),
        ),
    )
}

// Layout: `header (296B) || signature (64B)`
codec_fixtures!(SignedHeader, uncle(0x66) => "");

// Layout: `count (1B LE) || count × signed_header`.
codec_fixtures!(
    UncleHeaders,
    Self::empty() => "00",
    three_uncle_headers() => ""
);

/// The proposal of the proposal fixture.
pub fn proposal() -> Proposal {
    Proposal {
        header: header(0x00),
        uncle_headers: three_uncle_headers(),
        references: References {
            mempool_transactions: three_references(),
        },
        signature: Ed25519Signature::from_bytes(&[0x01u8; _]),
    }
}

// `header (296B) || uncle_headers (1B count + count * 360B)
// || references (50B) || signature (64B)` — 1491 bytes with three uncles.
//
// `references` is a `BoundedVec` capped at 1024, so it carries a 2-byte
// little-endian length prefix ahead of its 3 * 16-byte hash prefixes.
pub const PROPOSAL_HEX: &str = "";

codec_fixtures!(Proposal, proposal() => PROPOSAL_HEX);

/// The block of the block fixture: a real one, signed by its leader, with
/// three uncles and no transactions, so that it is one for every type of
/// transaction.
pub fn block<Tx>() -> Block<Tx>
where
    Tx: Hashable<Hash = TxHash> + StorageSize,
{
    let signing_key = Ed25519Key::from_bytes(&[0x01u8; 32]);
    let proof = Groth16LeaderProof::from_parts(
        lb_pol::PoLProof::from_bytes(&[0x22u8; _]),
        Fr::from(0x5555u64),
        signing_key.public_key(),
        VoucherCm::from(Fr::from(0x4444u64)),
    );
    Block::create(
        HeaderId::from([0x11u8; 32]),
        Slot::from(42u64),
        three_uncle_headers(),
        proof,
        BlockTransactions::empty(),
        &signing_key,
    )
    .expect("the fixture is a valid block")
}

// `header (296B) || uncle_headers (1B count + 3 * 360B) || transactions (2B
// count) || signature (64B)` — 1443 bytes.
pub const BLOCK_HEX: &str = "";

impl<Tx> lb_binary_codec::canonical::sealed::Sealed for Block<Tx> {}

impl<Tx> CodecExamples for Block<Tx>
where
    Tx: Hashable<Hash = TxHash> + StorageSize,
{
    fn fixtures() -> CodecFixtures<Self> {
        [CodecFixture {
            value: block(),
            bytes: Cow::Owned(decode_fixture_hex(BLOCK_HEX)),
        }]
        .into()
    }
}

